import{K as l,a as o,c as r,b as e,k as i,q as c,ac as h}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"Excel 入门、规范录入与练习数据","description":"工作簿、工作表、单元格与数据类型，创建 Excel 表格 Sales，排序筛选、冻结窗格、文本编号和统一订单练习数据。","frontmatter":{"title":"Excel 入门、规范录入与练习数据","description":"工作簿、工作表、单元格与数据类型，创建 Excel 表格 Sales，排序筛选、冻结窗格、文本编号和统一订单练习数据。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · Excel 表格与数据分析","summary":"工作簿、工作表、单元格与数据类型，创建 Excel 表格 Sales，排序筛选、冻结窗格、文本编号和统一订单练习数据。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":false,"next":{"text":"Excel 公式、相对引用与绝对引用","link":"/tools/office/excel/formulas"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"Excel 公式、相对引用与绝对引用","link":"/tools/office/excel/formulas"}},"headers":[],"relativePath":"tools/office/excel/start.md","filePath":"tools/office/excel/start.md"}'),s={name:"tools/office/excel/start.md"},u=Object.assign(s,{setup(n){const a={path:"/tools/office/excel/start",app:"Excel",title:"把八条订单变成能筛选的明细表",steps:[{tab:"插入",command:"表格",setting:"区域：A1:H9；勾选：表包含标题",anchor:"walkthrough-1"},{tab:"表格设计",command:"表名称",setting:"表名：Sales；字段：日期、部门、状态、金额",anchor:"walkthrough-2"},{tab:"视图",command:"冻结窗格",setting:"先选 A2；冻结首行；筛选状态：已完成",anchor:"walkthrough-3"}]};return(g,t)=>{const d=l("OfficeGuide");return o(),r("div",null,[t[0]||(t[0]=e("h1",{id:"excel-入门、规范录入与练习数据",tabindex:"-1"},[i("Excel 入门、规范录入与练习数据 "),e("a",{class:"header-anchor",href:"#excel-入门、规范录入与练习数据","aria-label":'Permalink to "Excel 入门、规范录入与练习数据"'},"​")],-1)),t[1]||(t[1]=e("p",null,"后续 Excel 章节围绕同一份虚构订单表展开。先把数据结构做对，公式、透视表和查询才能可靠；合并单元格、混合类型和隐藏小计行会让后续操作越来越难。",-1)),c(d,{guide:a}),t[2]||(t[2]=h('<h2 id="basics" tabindex="-1">工作簿与单元格 <a class="header-anchor" href="#basics" aria-label="Permalink to &quot;工作簿与单元格 {#basics}&quot;">​</a></h2><p>一个工作簿可以包含多个工作表，建议分别命名为 <code>订单</code>、<code>产品</code>、<code>汇总</code>，避免长期使用“Sheet1”。列用字母标识、行用数字标识，<code>A2</code> 是 A 列第 2 行，<code>A2:H9</code> 是矩形区域。名称框可直接输入地址跳转，编辑栏可查看完整内容。</p><p>单元格保存的是值或公式，显示格式决定它看起来怎样。数字 <code>0.15</code> 设成百分比显示为 <code>15%</code>，并没有变成 15；日期底层通常是序列值，设置日期格式才显示年月日。输入前设置文本格式可保存编号前导零和长编号，数据已经被截断后再改文本格式无法找回原值。</p><h2 id="data" tabindex="-1">建立八条订单 <a class="header-anchor" href="#data" aria-label="Permalink to &quot;建立八条订单 {#data}&quot;">​</a></h2><p>在 <code>订单</code> 表 A1:G9 输入下表。日期应被识别为真实日期，可先按本机支持的年月日格式输入；无法确认时使用 <code>=DATE(2026,10,1)</code> 等公式生成，再复制粘贴为值。</p><table tabindex="0"><thead><tr><th>订单号</th><th>日期</th><th>部门</th><th>产品</th><th style="text-align:right;">数量</th><th style="text-align:right;">单价</th><th>状态</th></tr></thead><tbody><tr><td>O001</td><td>2026-10-01</td><td>运营</td><td>键盘</td><td style="text-align:right;">2</td><td style="text-align:right;">120</td><td>已完成</td></tr><tr><td>O002</td><td>2026-10-02</td><td>技术</td><td>鼠标</td><td style="text-align:right;">3</td><td style="text-align:right;">80</td><td>已完成</td></tr><tr><td>O003</td><td>2026-10-03</td><td>财务</td><td>显示器</td><td style="text-align:right;">1</td><td style="text-align:right;">900</td><td>待处理</td></tr><tr><td>O004</td><td>2026-10-05</td><td>运营</td><td>鼠标</td><td style="text-align:right;">5</td><td style="text-align:right;">80</td><td>已完成</td></tr><tr><td>O005</td><td>2026-10-08</td><td>技术</td><td>键盘</td><td style="text-align:right;">4</td><td style="text-align:right;">120</td><td>已完成</td></tr><tr><td>O006</td><td>2026-10-11</td><td>财务</td><td>鼠标</td><td style="text-align:right;">2</td><td style="text-align:right;">80</td><td>已取消</td></tr><tr><td>O007</td><td>2026-10-15</td><td>运营</td><td>显示器</td><td style="text-align:right;">2</td><td style="text-align:right;">900</td><td>已完成</td></tr><tr><td>O008</td><td>2026-11-01</td><td>技术</td><td>显示器</td><td style="text-align:right;">1</td><td style="text-align:right;">900</td><td>已完成</td></tr></tbody></table><p>在 H1 输入“金额”，H2 输入 <code>=E2*F2</code>，向下填充到 H9。各行金额应为 240、240、900、400、480、160、1800、900；八行全部金额合计 <strong>5120</strong>。这是未排除待处理和取消状态的原始金额，不能直接称为已完成收入。</p><h2 id="table" tabindex="-1">转成 Excel 表格 <a class="header-anchor" href="#table" aria-label="Permalink to &quot;转成 Excel 表格 {#table}&quot;">​</a></h2><p>选中 A1:H9，按 <code>Ctrl+T</code>，确认范围和“表包含标题”。在“表格设计”中把表名改为 <code>Sales</code>。表格不是单纯的边框，它提供筛选按钮、自动扩展和结构化引用。金额列可改用 <code>=[@数量]*[@单价]</code>，其中 <code>@</code> 表示当前行。</p><p>数据表只保留一行字段名，一行一条记录，一列一种属性。日期列不要混入“本月小计”，数量列不要输入“2件”；单位放在列名或说明中。备注另设列，不在表内插入空行作为分组装饰。</p><h2 id="view" tabindex="-1">排序、筛选与冻结 <a class="header-anchor" href="#view" aria-label="Permalink to &quot;排序、筛选与冻结 {#view}&quot;">​</a></h2><p>点击表头筛选“状态 = 已完成”，可见六条订单。筛选隐藏了其他行，不代表删除数据。排序前确认操作作用于整张表；只给金额列排序会破坏订单与金额的对应关系。</p><p>要冻结首行，使用“视图 → 冻结窗格 → 冻结首行”；要同时冻结首行和第一列，可先选中 B2，再选择冻结窗格。冻结的位置由当前活动单元格上方和左侧决定，不影响打印时的重复标题设置。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>完成表格后检查：订单号八个且唯一，数量合计 20，金额合计 5120，筛选已完成剩六条。测试增加一条临时订单，观察表格范围和金额公式是否扩展；检查完撤销或删除该测试行，后续章节仍使用原始八条数据。</p><p>如果总数不符，先检查金额公式范围和数字类型，再检查是否有未清除的筛选。数据规范比表格颜色更重要。</p><p>参考入口：<a href="https://support.microsoft.com/en-us/excel/" target="_blank" rel="noopener noreferrer">Excel 帮助与学习</a>。</p><h2 id="walkthrough" tabindex="-1">图示跟做：把八条订单变成能筛选的明细表 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：把八条订单变成能筛选的明细表 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：先录入再建立表格 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：先录入再建立表格 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：插入 → 表格。</strong></p><p>按本篇数据表把八条订单录入 A1:G9，在 H1 输入金额，H2 输入 =E2*F2 并向下填充到 H9。选中 A1:H9，点击“插入 → 表格”，确认包含标题。日期应是真实日期；订单号和可能带前导零的编码应保留为文本。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：给后续公式一个稳定名称 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：给后续公式一个稳定名称 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：表格设计 → 表名称。</strong></p><p>选中表内任意格，找到表格设计中的表名称，改成 Sales 并回车。检查第一行是字段名、每列没有混入小计或空白标题。H2 应为 240，全表金额合计应为 5120；如果 H 列仍显示公式文字，先检查单元格格式及开头是否多了单引号。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：让查看与筛选不破坏数据 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：让查看与筛选不破坏数据 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：视图 → 冻结窗格。</strong></p><p>先冻结首行，向下滚动确认标题保留。点击状态列筛选箭头，只选已完成，应该留下六条记录。排序时使用表格标题上的菜单，使整行一起移动；不要只选部门一列排序，让订单归属错位。完成后清除筛选恢复八条。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>录入后优先检查八条订单、数量总计 20、金额总计 5120。筛选只隐藏行，不会删除未完成订单，汇总公式是否跟随筛选要由下一章明确决定。</p>',30))])}}});export{f as __pageData,u as default};
